def main():
    source = scan(SOURCE_ROOT / SOURCE_PATH)
    local = scan(LOCAL_DIR)
    changed = []
    for n, body in source.items():
        if n not in local or local[n] != body:
            changed.append(n)
    for n, body in local.items():
        if n not in source:
            changed.append(n)
    if not changed:
        print("no differences")
        return
    for n in sorted(changed):
        print("differs:", n)
